/* System clock frequency. */
extern uint32_t SystemCoreClock;

/*******************************************************************************
 ************************ BOARD_InitBootClocks function ************************
 ******************************************************************************/
void BOARD_InitBootClocks(void)
{
    BOARD_BootClockRUN();
}

/*******************************************************************************
 ********************** BOARD_BootClockRUN function ****************************
 ******************************************************************************/
void BOARD_BootClockRUN(void)
{
    /* Ensure the CSS main bus and processor clock divider is divide-by-1 so the
       core runs at the full FROL rate. */
    CLOCK_SetClockDiv(kCLOCK_DivCpuAhb, 1U);

    /* On FPGA only FROL can work, but by default PLL is selected. Attach FROL
       as the source of every clock selector so the design runs on FROL. */
    CLOCK_AttachClk(kFROL_to_MAIN_CLK);
    CLOCK_AttachClk(kFROL_to_XSPI);
    CLOCK_AttachClk(kFROL_to_UTICK);
    CLOCK_AttachClk(kFROL_to_GDET);
    CLOCK_AttachClk(kFROL_to_I3C);
    CLOCK_AttachClk(kFROL_to_PMRC);

    CLOCK_AttachClk(kFROL_to_CTIMER0);
    CLOCK_AttachClk(kFROL_to_CTIMER1);
    CLOCK_AttachClk(kFROL_to_CTIMER2);
    CLOCK_AttachClk(kFROL_to_CTIMER3);
    CLOCK_AttachClk(kFROL_to_CTIMER4);
    CLOCK_AttachClk(kFROL_to_FLEXCOMM0);
    CLOCK_AttachClk(kFROL_to_FLEXCOMM1);
    CLOCK_AttachClk(kFROL_to_FLEXCOMM2);
    CLOCK_AttachClk(kFROL_to_FLEXCOMM3);
    CLOCK_AttachClk(kFROL_to_FLEXCOMM4);
    CLOCK_AttachClk(kFROL_to_FLEXCOMM5);

    CLOCK_AttachClk(kFROL_to_ADSS_MAIN);
    CLOCK_AttachClk(kFROL_to_ADSS_DP0_INT);
    CLOCK_AttachClk(kFROL_to_ADSS_DP1_INT);
    CLOCK_AttachClk(kFROL_to_ADSS_DP2_INT);
    CLOCK_AttachClk(kFROL_to_ADSS_DP3_INT);

    CLOCK_AttachClk(kFROL_to_NSS_MAIN);
    CLOCK_AttachClk(kFROL_to_NSS_XSPI);

    CLOCK_AttachClk(kFROL_to_VISION);

    /* Update the system core clock frequency with the configured value. */
    SystemCoreClock = BOARD_BOOTCLOCKRUN_CORE_CLOCK;
}

#endif
